from typing import Sequence, Union, Any, get_origin, get_args
try:
    from types import UnionType
except ImportError:
    UnionType = Union
from pydantic import Json
import collections
from collections import deque

sequence_types = (Sequence, list, tuple, set, frozenset, deque)

def lenient_issubclass(cls, types):
    try:
        return issubclass(cls, types)
    except:
        return False

def _annotation_is_sequence(annotation):
    if lenient_issubclass(annotation, (str, bytes)):
        return False
    return lenient_issubclass(annotation, sequence_types)

def field_annotation_is_sequence(annotation):
    origin = get_origin(annotation)
    if origin is Union or (UnionType is not Union and origin is UnionType):
        for arg in get_args(annotation):
            if field_annotation_is_sequence(arg):
                return True
        return False
    return _annotation_is_sequence(annotation) or _annotation_is_sequence(
        get_origin(annotation)
    )

